{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.offline_metafield_ideal_mix AS WITH category_mix AS ( SELECT store_code AS branch_code, store AS branch_name, category, CAST(NULLIF(TRIM(category_mix), \'\') AS DECIMAL(10,4)) * 100 AS category_ideal_mix_pct FROM snitch_db.maplemonk.gs_sheet3 ), metafield_mix AS ( SELECT t.branch_code, t.marketplace_mapped, t.category, t.collar AS meta_1, t.designs AS meta_2, CAST(NULLIF(TRIM(REPLACE(t.ideal_mix, \'%\', \'\')), \'\') AS DECIMAL(10,4)) AS meta_mix_pct FROM snitch_db.maplemonk.gs_t_shirts_ideal_mix t UNION ALL SELECT s.branch_code, s.marketplace_mapped, s.category, s.designs AS meta_1, IFNULL(s.material, \'N/A\') AS meta_2, CAST(NULLIF(TRIM(REPLACE(s.ideal_mix, \'%\', \'\')), \'\') AS DECIMAL(10,4)) AS meta_mix_pct FROM snitch_db.maplemonk.gs_shirts_ideal_mix s UNION ALL SELECT tr.\"BRANCH CODE\", tr.store, tr.category, tr.meta1 AS meta_1, \'N/A\' AS meta_2, CAST(NULLIF(TRIM(tr.\"META MIX\"), \'\') AS DECIMAL(10,4)) * 100 AS meta_mix_pct FROM snitch_db.maplemonk.offline_ideal_trousers_v1 tr UNION ALL SELECT j.\"BRANCH CODE\", j.store, j.category, j.meta1 AS meta_1, \'N/A\' AS meta_2, CAST(NULLIF(TRIM(j.\"META MIX\"), \'\') AS DECIMAL(10,4)) * 100 AS meta_mix_pct FROM snitch_db.maplemonk.offline_ideal_jeans_v1 j ), meta_computed AS ( SELECT m.branch_code, m.marketplace_mapped, m.category, c.category_ideal_mix_pct AS cat_mix, m.meta_1, m.meta_2, m.meta_mix_pct, ROUND( (m.meta_mix_pct / 100) * (c.category_ideal_mix_pct / 100), 6 ) * 100 AS metafield_ideal_mix FROM metafield_mix m JOIN category_mix c ON m.branch_code = c.branch_code AND UPPER(TRIM(m.category)) = UPPER(TRIM(c.category)) WHERE m.meta_mix_pct > 0 AND c.category_ideal_mix_pct > 0 ), fallback_general AS ( SELECT c.branch_code, c.branch_name AS marketplace_mapped, c.category, c.category_ideal_mix_pct AS cat_mix, \'GENERAL\' AS meta_1, \'GENERAL\' AS meta_2, 100.0000 AS meta_mix_pct, c.category_ideal_mix_pct AS metafield_ideal_mix FROM category_mix c WHERE c.category_ideal_mix_pct > 0 AND UPPER(TRIM(c.category)) NOT IN (\'T-SHIRTS\', \'SHIRTS\', \'TROUSERS\', \'JEANS\') ) SELECT branch_code, marketplace_mapped, category, cat_mix, meta_1, meta_2, meta_mix_pct, metafield_ideal_mix FROM meta_computed UNION ALL SELECT branch_code, marketplace_mapped, category, cat_mix, meta_1, meta_2, meta_mix_pct, metafield_ideal_mix FROM fallback_general ORDER BY branch_code, category, metafield_ideal_mix DESC; CREATE or replace table snitch_db.maplemonk.offline_metafield_normalized_str as WITH mapped AS ( SELECT branch_code, marketplace_mapped AS store_name, CASE WHEN UPPER(TRIM(new_category)) = \'CHINOS\' THEN \'TROUSERS\' ELSE COALESCE(NULLIF(UPPER(TRIM(new_category)), \'\'), \'NO_CATEGORY\') END AS category, CASE WHEN UPPER(COALESCE(new_category,\'\')) LIKE \'%T-SHIRTS%\' THEN CASE WHEN UPPER(TRIM(designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(designs)) = \'GRAPHIC PRINT\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) IN (\'TEXTURED\',\'SELF DESIGN\') THEN \'Self Design & Textured\' WHEN UPPER(TRIM(designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(designs)) = \'FLORAL\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'TIE & DYE\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'PRINTED\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'GEOMETRIC\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'ANIMAL PRINT\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) IN (\'EMBROIDED\',\'EMBELLISHED\') THEN \'Embroided\' ELSE \'Others\' END WHEN UPPER(COALESCE(new_category,\'\')) LIKE \'%SHIRTS%\' THEN CASE WHEN style ILIKE \'%Linen%\' THEN \'Linen\' WHEN style ILIKE \'%Luxe%\' THEN \'Snitch LUXE\' WHEN UPPER(TRIM(designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(designs)) IN (\'TEXTURED\',\'SELF DESIGN\') THEN \'Self Design & Textured\' WHEN UPPER(TRIM(designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(designs)) IN (\'PRINTED\',\'FLORAL\',\'GEOMETRIC\',\'TIE & DYE\',\'GRAPHIC PRINT\',\'ANIMAL PRINT\') THEN \'Printed\' WHEN UPPER(TRIM(designs)) IN (\'EMBROIDED\',\'EMBELLISHED\') THEN \'Embroided\' ELSE \'Others\' END ELSE designs END AS designs_new, CASE WHEN UPPER(COALESCE(new_category,\'\')) LIKE \'%T-SHIRTS%\' THEN CASE WHEN TRIM(LOWER(collar_new)) IN (\'mock\',\'spread\',\'cuban\',\'mandarin\',\'baseball\',\'high neck\',\'zip\',\'others\') THEN \'Others\' WHEN TRIM(LOWER(collar_new)) IN (\'v neck\',\'crew\',\'round\') THEN \'Round\' WHEN TRIM(LOWER(collar_new)) = \'polo\' THEN \'Polo\' ELSE \'Others\' END ELSE NULL END AS collar_new_std, CASE WHEN UPPER(TRIM(new_category)) = \'JEANS\' THEN CASE WHEN UPPER(TRIM(fit)) IN ( \'TAPERED FIT\',\'REGULAR FIT\',\'RELAXED FIT\',\'STRAIGHT FIT\', \'COMFORT FIT\',\'LOOSE FIT\',\'STRAIGHT LOOSE FIT\' ) THEN \'Straight Fit\' WHEN UPPER(TRIM(fit)) IN ( \'SUPER BAGGY FIT\',\'SLOUCHY FIT\',\'BAGGY FIT\' ) THEN \'Baggy Fit\' WHEN UPPER(TRIM(fit)) IN (\'BOOTCUT\',\'FLARED FIT\') THEN \'Bootcut\' WHEN UPPER(TRIM(fit)) IN (\'CARROT FIT\',\'BALLOON FIT\') THEN \'Carrot Fit\' WHEN UPPER(TRIM(fit)) = \'SLIM FIT\' THEN \'Slim Fit\' WHEN UPPER(TRIM(fit)) = \'SKINNY FIT\' THEN \'Skinny Fit\' ELSE \'Straight Fit\' END WHEN UPPER(TRIM(new_category)) IN (\'TROUSERS\',\'CHINOS\') THEN CASE WHEN UPPER(TRIM(fit)) IN (\'BAGGY FIT\',\'BELLBOTTOM FIT\') THEN \'Baggy Fit\' WHEN UPPER(TRIM(fit)) IN (\'CARROT FIT\',\'BALLOON FIT\') THEN \'Carrot Fit\' WHEN UPPER(TRIM(fit)) IN ( \'CUSTOM FIT\',\'CUSTOM REGULAR FIT\',\'CUSTOM STRAIGHT FIT\' ) THEN \'Custom Fit\' WHEN UPPER(TRIM(fit)) IN (\'LOOSE FIT\',\'WIDE FIT\',\'WIDE LEG\') THEN \'Loose Fit\' WHEN UPPER(TRIM(fit)) = \'SLIM FIT\' THEN \'Slim Fit\' WHEN UPPER(TRIM(fit)) IN ( \'COMFORT FIT\',\'REGULAR FIT\',\'RELAXED FIT\',\'STRAIGHT FIT\' ) THEN \'Straight Fit\' ELSE \'Straight Fit\' END ELSE COALESCE(fit,\'No_fit\') END AS fit, opening_inventory_7d, closing_inventory_7d, sales_qty_7d, opening_inventory_15d, closing_inventory_15d, sales_qty_15d, opening_inventory_30d, closing_inventory_30d, sales_qty_30d FROM snitch_db.maplemonk.offline_metafield_str ), meta_base AS ( SELECT branch_code, store_name, category, CASE WHEN UPPER(category) IN (\'TROUSERS\',\'JEANS\') THEN COALESCE(fit, \'No_fit\') WHEN UPPER(category) LIKE \'%T-SHIRTS%\' THEN COALESCE(collar_new_std, \'Others\') WHEN UPPER(category) in (\'SHIRTS\') THEN COALESCE(designs_new, \'Other\') ELSE category END AS meta1, CASE WHEN UPPER(category) LIKE \'%T-SHIRTS%\' THEN COALESCE(designs_new, \'Others\') ELSE \'N/A\' END AS meta2, opening_inventory_7d, closing_inventory_7d, sales_qty_7d, opening_inventory_15d, closing_inventory_15d, sales_qty_15d, opening_inventory_30d, closing_inventory_30d, sales_qty_30d FROM mapped ) SELECT branch_code, store_name, category, meta1, meta2, ROUND( 100 * SUM(sales_qty_7d) / NULLIF( (SUM(opening_inventory_7d) + SUM(closing_inventory_7d)) / 2.0, 0 ), 2 ) AS str_7d_pct, ROUND( 100 * SUM(sales_qty_15d) / NULLIF( (SUM(opening_inventory_15d) + SUM(closing_inventory_15d)) / 2.0, 0 ), 2 ) AS str_15d_pct, ROUND( 100 * SUM(sales_qty_30d) / NULLIF( (SUM(opening_inventory_30d) + SUM(closing_inventory_30d)) / 2.0, 0 ), 2 ) AS str_30d_pct FROM meta_base GROUP BY branch_code, store_name, category, meta1, meta2 HAVING SUM(sales_qty_30d) > 0 OR (SUM(opening_inventory_30d) + SUM(closing_inventory_30d)) > 0 ORDER BY branch_code, category, meta1, meta2; create or replace table snitch_db.maplemonk.offline_metafield_delta as WITH store_map AS ( SELECT DISTINCT BRANCH_CODE AS Branch_code, MARKETPLACE_MAPPED AS Store_name, STATE AS STATE, AM AS AREA_MANAGER FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ), metafields_std AS ( SELECT om.sku_group, MAX(om.new_category) AS category, MAX(CASE WHEN UPPER(om.new_category) LIKE \'%T-SHIRTS%\' THEN CASE WHEN UPPER(TRIM(om.designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(om.designs)) = \'GRAPHIC PRINT\' THEN \'Graphic Print\' WHEN UPPER(TRIM(om.designs)) = \'TEXTURED\' THEN \'Self Design & Textured\' WHEN UPPER(TRIM(om.designs)) = \'SELF DESIGN\' THEN \'Self Design & Textured\' WHEN UPPER(TRIM(om.designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(om.designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(om.designs)) = \'PRINTED\' THEN \'Graphic Print\' WHEN UPPER(TRIM(om.designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(om.designs)) = \'GEOMETRIC\' THEN \'Graphic Print\' WHEN UPPER(TRIM(om.designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(om.designs)) = \'FLORAL\' THEN \'Graphic Print\' WHEN UPPER(TRIM(om.designs)) = \'TIE & DYE\' THEN \'Graphic Print\' WHEN UPPER(TRIM(om.designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(om.designs)) = \'ANIMAL PRINT\' THEN \'Graphic Print\' ELSE \'Others\' END WHEN UPPER(om.new_category) LIKE \'%SHIRTS%\' THEN CASE WHEN om.style ILIKE \'%Linen%\' THEN \'Linen\' WHEN om.style ILIKE \'%Luxe%\' THEN \'Snitch LUXE\' WHEN UPPER(TRIM(om.designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(om.designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(om.designs)) = \'TEXTURED\' THEN \'Self Design & Textured\' WHEN UPPER(TRIM(om.designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(om.designs)) = \'SELF DESIGN\' THEN \'Self Design & Textured\' WHEN UPPER(TRIM(om.designs)) = \'PRINTED\' THEN \'Printed\' WHEN UPPER(TRIM(om.designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(om.designs)) = \'FLORAL\' THEN \'Printed\' WHEN UPPER(TRIM(om.designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(om.designs)) = \'GEOMETRIC\' THEN \'Printed\' WHEN UPPER(TRIM(om.designs)) = \'TIE & DYE\' THEN \'Printed\' WHEN UPPER(TRIM(om.designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(om.designs)) = \'GRAPHIC PRINT\' THEN \'Printed\' WHEN UPPER(TRIM(om.designs)) = \'ANIMAL PRINT\' THEN \'Printed\' ELSE \'Others\' END ELSE om.designs END) AS designs_new, MAX(CASE WHEN UPPER(om.new_category) LIKE \'%T-SHIRTS%\' THEN CASE WHEN TRIM(LOWER(om.collar_new)) IN (\'mock\',\'spread\',\'cuban\',\'mandarin\',\'baseball\',\'high neck\',\'zip\',\'others\') THEN \'Others\' WHEN TRIM(LOWER(om.collar_new)) IN (\'v neck\',\'crew\',\'round\') THEN \'Round\' WHEN TRIM(LOWER(om.collar_new)) = \'polo\' THEN \'Polo\' ELSE \'Others\' END ELSE NULL END) AS collar_new_std, MAX( CASE WHEN UPPER(TRIM(om.new_category)) = \'JEANS\' THEN CASE WHEN UPPER(TRIM(om.fit)) IN ( \'TAPERED FIT\',\'REGULAR FIT\',\'RELAXED FIT\',\'STRAIGHT FIT\', \'COMFORT FIT\',\'LOOSE FIT\',\'STRAIGHT LOOSE FIT\' ) THEN \'Straight Fit\' WHEN UPPER(TRIM(om.fit)) IN ( \'SUPER BAGGY FIT\',\'SLOUCHY FIT\',\'BAGGY FIT\' ) THEN \'Baggy Fit\' WHEN UPPER(TRIM(om.fit)) IN (\'BOOTCUT\',\'FLARED FIT\') THEN \'Bootcut\' WHEN UPPER(TRIM(om.fit)) IN (\'CARROT FIT\',\'BALLOON FIT\') THEN \'Carrot Fit\' WHEN UPPER(TRIM(om.fit)) = \'SLIM FIT\' THEN \'Slim Fit\' WHEN UPPER(TRIM(om.fit)) = \'SKINNY FIT\' THEN \'Skinny Fit\' ELSE \'Straight Fit\' END WHEN UPPER(TRIM(om.new_category)) IN (\'TROUSERS\',\'CHINOS\') THEN CASE WHEN UPPER(TRIM(om.fit)) IN (\'BAGGY FIT\',\'BELLBOTTOM FIT\') THEN \'Baggy Fit\' WHEN UPPER(TRIM(om.fit)) IN (\'CARROT FIT\',\'BALLOON FIT\') THEN \'Carrot Fit\' WHEN UPPER(TRIM(om.fit)) IN ( \'CUSTOM FIT\',\'CUSTOM REGULAR FIT\',\'CUSTOM STRAIGHT FIT\' ) THEN \'Custom Fit\' WHEN UPPER(TRIM(om.fit)) IN (\'LOOSE FIT\',\'WIDE FIT\',\'WIDE LEG\') THEN \'Loose Fit\' WHEN UPPER(TRIM(om.fit)) = \'SLIM FIT\' THEN \'Slim Fit\' WHEN UPPER(TRIM(om.fit)) IN ( \'COMFORT FIT\',\'REGULAR FIT\',\'RELAXED FIT\',\'STRAIGHT FIT\' ) THEN \'Straight Fit\' ELSE \'Straight Fit\' END ELSE NULL END ) AS fit_normalized FROM snitch_db.maplemonk.offline_master om GROUP BY 1 ), size_health AS ( SELECT sku_group, branch_code, CASE WHEN REGEXP_LIKE( UPPER(sku_group), \'^(4MBG|4BRN|4BPL|4BTR|4BCH|4BJE|4BJK|4BSW|4BHD|4BOS|4BSHS|4BSFS|4BSH|4BBL|4BCA|4BSWT|4BCD|4BJO).*\' ) AND ( IFF(COALESCE(XL3_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(XL4_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(XL5_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(XL6_UNITS, 0) > 0, 1, 0) ) >= 3 THEN 1 WHEN NOT REGEXP_LIKE( UPPER(sku_group), \'^(4MBG|4BRN|4BPL|4BTR|4BCH|4BJE|4BJK|4BSW|4BHD|4BOS|4BSHS|4BSFS|4BSH|4BBL|4BCA|4BSWT|4BCD|4BJO).*\' ) AND ( IFF(COALESCE(S_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(M_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(L_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(XL_UNITS, 0) > 0, 1, 0) ) >= 3 AND ( IFF(COALESCE(XS_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(S_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(M_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(L_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(XL_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(XXL_UNITS, 0) > 0, 1, 0) ) >= 4 THEN 1 ELSE 0 END AS is_full_size_store, CASE WHEN COALESCE(inventory, 0) = 0 AND REGEXP_LIKE( UPPER(sku_group), \'^(4MBG|4BRN|4BPL|4BTR|4BCH|4BJE|4BJK|4BSW|4BHD|4BOS|4BSHS|4BSFS|4BSH|4BBL|4BCA|4BSWT|4BCD|4BJO).*\' ) AND ( IFF(COALESCE(JIT_3XL_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(JIT_4XL_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(JIT_5XL_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(JIT_6XL_UNITS, 0) > 0, 1, 0) ) >= 3 THEN 1 WHEN COALESCE(inventory, 0) = 0 AND NOT REGEXP_LIKE( UPPER(sku_group), \'^(4MBG|4BRN|4BPL|4BTR|4BCH|4BJE|4BJK|4BSW|4BHD|4BOS|4BSHS|4BSFS|4BSH|4BBL|4BCA|4BSWT|4BCD|4BJO).*\' ) AND ( IFF(COALESCE(JIT_S_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(JIT_M_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(JIT_L_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(JIT_XL_UNITS, 0) > 0, 1, 0) ) >= 3 AND ( IFF(COALESCE(JIT_XS_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(JIT_S_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(JIT_M_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(JIT_L_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(JIT_XL_UNITS, 0) > 0, 1, 0) + IFF(COALESCE(JIT_2XL_UNITS, 0) > 0, 1, 0) ) >= 4 THEN 1 ELSE 0 END AS is_full_size_transit FROM snitch_db.maplemonk.offline_master WHERE COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 ), sku_live_mrp AS ( SELECT REGEXP_REPLACE( UPPER(TRIM( CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C-%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END )), \'[^A-Z0-9]\', \'\' ) AS clean_sku_group, MAX(TRY_TO_NUMBER(mrp)) AS live_mrp FROM snitch_db.maplemonk.unicommerce_live_inventory WHERE TRY_TO_NUMBER(mrp) > 0 GROUP BY 1 ), sku_price_bucket AS ( SELECT clean_sku_group, live_mrp, CASE WHEN live_mrp < 999 THEN \'VALUE\' WHEN live_mrp < 1500 THEN \'MID\' WHEN live_mrp < 2500 THEN \'PREMIUM\' ELSE \'SUPER_PREMIUM\' END AS price_tier, CASE WHEN live_mrp < 999 THEN FLOOR(live_mrp / 200) * 200 WHEN live_mrp < 1500 THEN 999 + FLOOR((live_mrp - 999) / 200) * 200 WHEN live_mrp < 2500 THEN 1500 + FLOOR((live_mrp - 1500) / 200) * 200 ELSE 2500 + FLOOR((live_mrp - 2500) / 200) * 200 END AS slab_min_price FROM sku_live_mrp ), price_bucket_map AS ( SELECT clean_sku_group, live_mrp, price_tier, slab_min_price, CASE WHEN price_tier = \'VALUE\' THEN LEAST(slab_min_price + 199, 998) WHEN price_tier = \'MID\' THEN LEAST(slab_min_price + 199, 1499) WHEN price_tier = \'PREMIUM\' THEN LEAST(slab_min_price + 199, 2499) ELSE slab_min_price + 199 END AS slab_max_price, CONCAT( CHR(8377), CAST(slab_min_price AS INTEGER), \' - \', CHR(8377), CAST( CASE WHEN price_tier = \'VALUE\' THEN LEAST(slab_min_price + 199, 998) WHEN price_tier = \'MID\' THEN LEAST(slab_min_price + 199, 1499) WHEN price_tier = \'PREMIUM\' THEN LEAST(slab_min_price + 199, 2499) ELSE slab_min_price + 199 END AS INTEGER ) ) AS price_range_label FROM sku_price_bucket ), delta_sku_meta AS ( SELECT DISTINCT TO_VARCHAR(om.branch_code) AS branch_code, REGEXP_REPLACE(UPPER(TRIM(om.sku_group)), \'[^A-Z0-9]\', \'\') AS clean_sku_group, CASE WHEN UPPER(TRIM(om.new_category)) = \'CHINOS\' THEN \'TROUSERS\' ELSE COALESCE(NULLIF(UPPER(TRIM(om.new_category)), \'\'), \'NO_CATEGORY\') END AS category, CASE WHEN UPPER(TRIM(COALESCE(om.new_category, \'\'))) IN (\'TROUSERS\',\'CHINOS\',\'JEANS\') THEN COALESCE(ms.fit_normalized, \'Straight Fit\') WHEN UPPER(COALESCE(om.new_category, \'\')) LIKE \'%T-SHIRTS%\' THEN COALESCE(ms.collar_new_std, \'Others\') WHEN UPPER(COALESCE(om.new_category, \'\')) LIKE \'%SHIRTS%\' THEN COALESCE(ms.designs_new, \'Other\') ELSE COALESCE(om.new_category, \'No_CATEGORY\') END AS meta1, CASE WHEN UPPER(COALESCE(om.new_category, \'\')) LIKE \'%T-SHIRTS%\' THEN COALESCE(ms.designs_new, \'Others\') ELSE \'N/A\' END AS meta2 FROM snitch_db.maplemonk.offline_master om LEFT JOIN metafields_std ms ON om.sku_group = ms.sku_group WHERE om.sku_group IS NOT NULL ), bucket_inventory AS ( SELECT d.branch_code, d.category, d.meta1, d.meta2, p.price_tier, p.slab_min_price, p.slab_max_price, p.price_range_label, SUM(COALESCE(om.inventory, 0) + COALESCE(om.jit_qty, 0)) AS bucket_inventory_units FROM snitch_db.maplemonk.offline_master om JOIN delta_sku_meta d ON TO_VARCHAR(om.branch_code) = d.branch_code AND REGEXP_REPLACE(UPPER(TRIM(om.sku_group)), \'[^A-Z0-9]\', \'\') = d.clean_sku_group JOIN price_bucket_map p ON d.clean_sku_group = p.clean_sku_group GROUP BY 1,2,3,4,5,6,7,8 ), bucket_sales AS ( SELECT d.branch_code, d.category, d.meta1, d.meta2, p.price_tier, p.slab_min_price, p.slab_max_price, p.price_range_label, SUM(TRY_TO_NUMBER(s.selling_price)) AS actual_revenue FROM snitch_db.maplemonk.store_fact_items_offline s JOIN delta_sku_meta d ON TO_VARCHAR(s.branch_code) = d.branch_code AND REGEXP_REPLACE(UPPER(TRIM(s.sku_group)), \'[^A-Z0-9]\', \'\') = d.clean_sku_group JOIN price_bucket_map p ON d.clean_sku_group = p.clean_sku_group WHERE TO_DATE(s.order_date) BETWEEN DATEADD(DAY, -29, CURRENT_DATE()) AND CURRENT_DATE() AND COALESCE(UPPER(TRIM(s.doc_prefix)), \'\') NOT IN (\'OMS\',\'QCOM\') AND COALESCE(UPPER(TRIM(s.sku_group)), \'\') NOT LIKE \'CB%\' AND COALESCE(UPPER(TRIM(s.sku_group)), \'\') NOT LIKE \'NT%\' AND TRY_TO_NUMBER(s.selling_price) > 0 GROUP BY 1,2,3,4,5,6,7,8 ), bucket_performance AS ( SELECT COALESCE(s.branch_code, i.branch_code) AS branch_code, COALESCE(s.category, i.category) AS category, COALESCE(s.meta1, i.meta1) AS meta1, COALESCE(s.meta2, i.meta2) AS meta2, COALESCE(s.price_tier, i.price_tier) AS price_tier, COALESCE(s.slab_min_price, i.slab_min_price) AS slab_min_price, COALESCE(s.slab_max_price, i.slab_max_price) AS slab_max_price, COALESCE(s.price_range_label, i.price_range_label) AS price_range_label, COALESCE(i.bucket_inventory_units, 0) AS bucket_inventory_units, COALESCE(s.actual_revenue, 0) AS actual_revenue, DIV0( COALESCE(s.actual_revenue, 0), SUM(COALESCE(s.actual_revenue, 0)) OVER ( PARTITION BY COALESCE(s.branch_code, i.branch_code), COALESCE(s.category, i.category), COALESCE(s.meta1, i.meta1), COALESCE(s.meta2, i.meta2) ) ) AS revenue_share FROM bucket_sales s FULL OUTER JOIN bucket_inventory i ON s.branch_code = i.branch_code AND UPPER(TRIM(s.category)) = UPPER(TRIM(i.category)) AND UPPER(TRIM(s.meta1)) = UPPER(TRIM(i.meta1)) AND UPPER(TRIM(s.meta2)) = UPPER(TRIM(i.meta2)) AND s.slab_min_price = i.slab_min_price ), top_price_bucket AS ( SELECT branch_code, category, meta1, meta2, price_range_label AS top_price_bucket FROM bucket_performance WHERE actual_revenue > 0 QUALIFY ROW_NUMBER() OVER ( PARTITION BY branch_code, category, meta1, meta2 ORDER BY revenue_share DESC, actual_revenue DESC, slab_min_price ASC ) = 1 ) base AS ( SELECT om.Branch_code, CASE WHEN UPPER(TRIM(om.new_CATEGORY)) = \'CHINOS\' THEN \'TROUSERS\' ELSE COALESCE(NULLIF(UPPER(TRIM(om.new_CATEGORY)), \'\'), \'NO_CATEGORY\') END AS CATEGORY, CASE WHEN UPPER(TRIM(COALESCE(om.new_CATEGORY, \'\'))) IN (\'TROUSERS\',\'CHINOS\',\'JEANS\') THEN COALESCE(ms.fit_normalized, \'Straight Fit\') WHEN UPPER(COALESCE(om.new_CATEGORY, \'\')) LIKE \'%T-SHIRTS%\' THEN COALESCE(ms.collar_new_std, \'Others\') WHEN UPPER(COALESCE(om.new_CATEGORY, \'\')) LIKE \'%SHIRTS%\' THEN COALESCE(ms.designs_new, \'Other\') ELSE COALESCE(om.new_CATEGORY, \'No_CATEGORY\') END AS META1, CASE WHEN UPPER(COALESCE(om.new_CATEGORY, \'\')) LIKE \'%T-SHIRTS%\' THEN COALESCE(ms.designs_new, \'Others\') ELSE \'N/A\' END AS META2, SUM(COALESCE(om.SALES_LAST_7_DAYS, 0)) AS SALES_7D, SUM(COALESCE(om.SALES_LAST_15_DAYS, 0)) AS SALES_15D, SUM(COALESCE(om.SALES_LAST_30_DAYS, 0)) AS SALES_30D, SUM(COALESCE(om.Inventory, 0) + COALESCE(om.JIT_QTY, 0)) AS INV_UNITS, SUM(COALESCE(sh.is_full_size_store, 0)) AS FULL_SIZE_STORE_COUNT, SUM(COALESCE(sh.is_full_size_transit, 0)) AS FULL_SIZE_TRANSIT_COUNT, COUNT(om.sku_group) AS TOTAL_OPTIONS_COUNT, MAX(om.base_stock) AS STORE_BASE_STOCK, MAX(om.dept_ideal) AS DEPTH_VAL FROM snitch_db.maplemonk.offline_master om LEFT JOIN metafields_std ms ON om.sku_group = ms.sku_group LEFT JOIN size_health sh ON om.sku_group = sh.sku_group AND om.branch_code = sh.branch_code GROUP BY 1,2,3,4 ), totals AS ( SELECT b.*, SUM(b.SALES_7D) OVER (PARTITION BY b.Branch_code) AS STORE_SALES_7D, SUM(b.SALES_15D) OVER (PARTITION BY b.Branch_code) AS STORE_SALES_15D, SUM(b.SALES_30D) OVER (PARTITION BY b.Branch_code) AS STORE_SALES_30D, SUM(b.INV_UNITS) OVER (PARTITION BY b.Branch_code) AS STORE_INV_UNITS, MAX(b.STORE_BASE_STOCK) OVER (PARTITION BY b.Branch_code) AS FINAL_STORE_BASE_STOCK FROM base b ), metrics AS ( SELECT t.*, ROUND(100 * t.SALES_7D / NULLIF(t.STORE_SALES_7D, 0), 2) AS SALES_MIX_7D_PCT, ROUND(100 * t.SALES_15D / NULLIF(t.STORE_SALES_15D, 0), 2) AS SALES_MIX_15D_PCT, ROUND(100 * t.SALES_30D / NULLIF(t.STORE_SALES_30D, 0), 2) AS SALES_MIX_30D_PCT, ROUND(100 * t.INV_UNITS / NULLIF(t.STORE_INV_UNITS, 0), 2) AS INV_MIX_PCT, str.str_7d_pct AS STR_7D_PCT, str.str_15d_pct AS STR_15D_PCT, str.str_30d_pct AS STR_30D_PCT FROM totals t LEFT JOIN snitch_db.maplemonk.OFFLINE_METAFIELD_NORMALIZED_STR str ON t.branch_code = str.branch_code AND UPPER(TRIM(t.category)) = UPPER(TRIM(str.category)) AND UPPER(TRIM(t.meta1)) = UPPER(TRIM(str.meta1)) AND UPPER(TRIM(t.meta2)) = UPPER(TRIM(str.meta2)) ), final_metrics AS ( SELECT m.*, ROUND( 0.5 * COALESCE(m.STR_7D_PCT, 0) + 0.3 * COALESCE(m.STR_15D_PCT, 0) + 0.2 * COALESCE(m.STR_30D_PCT, 0), 2 ) AS OPPORTUNITY_STR_PCT, ROUND( 0.5 * COALESCE(m.SALES_MIX_7D_PCT, 0) + 0.3 * COALESCE(m.SALES_MIX_15D_PCT, 0) + 0.2 * COALESCE(m.SALES_MIX_30D_PCT, 0), 2 ) AS OPPORTUNITY_SALES_MIX_PCT, CASE WHEN LOWER(TRIM(m.category)) = \'jeans\' THEN m.DEPTH_VAL * 1.3 WHEN LOWER(TRIM(m.category)) = \'trousers\' THEN m.DEPTH_VAL * 1.2 ELSE m.DEPTH_VAL END AS EFFECTIVE_DEPTH FROM metrics m ) SELECT f.Branch_code, sm.Store_name, SM.STATE, SM.AREA_MANAGER, f.CATEGORY, f.META1, f.META2, tpb.top_price_bucket AS TOP_PRICE_BUCKET, f.SALES_7D, f.SALES_15D, f.SALES_30D, f.INV_UNITS, f.SALES_MIX_7D_PCT, f.SALES_MIX_15D_PCT, f.SALES_MIX_30D_PCT, f.STR_7D_PCT, f.STR_15D_PCT, f.STR_30D_PCT, f.OPPORTUNITY_STR_PCT, f.final_store_base_stock AS base_stock, idl.cat_mix, idl.meta_mix_pct, CEIL( ( COALESCE(f.FINAL_STORE_BASE_STOCK, 0) * (COALESCE(idl.metafield_ideal_mix, 0) / 100.0) ) / NULLIF(f.EFFECTIVE_DEPTH, 0) ) AS IDEAL_OPTIONS, f.FULL_SIZE_STORE_COUNT AS ACTUAL_FULL_SIZE_STORE, f.FULL_SIZE_TRANSIT_COUNT AS ACTUAL_FULL_SIZE_TRANSIT, f.OPPORTUNITY_SALES_MIX_PCT, f.INV_MIX_PCT, COALESCE(idl.metafield_ideal_mix, 0) AS IDEAL_MIX_PCT, CASE WHEN (f.OPPORTUNITY_SALES_MIX_PCT > f.INV_MIX_PCT) AND (f.OPPORTUNITY_SALES_MIX_PCT < idl.metafield_ideal_mix) THEN \'Allocate\' WHEN (f.OPPORTUNITY_SALES_MIX_PCT > f.INV_MIX_PCT) AND (f.OPPORTUNITY_SALES_MIX_PCT > idl.metafield_ideal_mix) THEN \'Allocate and Redefine\' WHEN (f.OPPORTUNITY_SALES_MIX_PCT < f.INV_MIX_PCT) AND (f.INV_MIX_PCT > idl.metafield_ideal_mix) THEN \'RTV\' WHEN (f.OPPORTUNITY_SALES_MIX_PCT < f.INV_MIX_PCT) AND (f.INV_MIX_PCT < idl.metafield_ideal_mix) THEN \'Review\' ELSE \'Review\' END AS INVENTORY_ACTION_ITEM, ROUND( COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0), 2 ) AS DELTA_PCT, CEIL( CASE WHEN (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) > 3 THEN GREATEST( GREATEST( 0, COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (COALESCE(idl.metafield_ideal_mix,0) / 100.0)) / NULLIF(f.EFFECTIVE_DEPTH,0) ), 0 ) - COALESCE(f.FULL_SIZE_STORE_COUNT + f.FULL_SIZE_TRANSIT_COUNT,0) ), COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (3.0/100.0)) / NULLIF(f.EFFECTIVE_DEPTH,0) ), 0 ) ) WHEN (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) > 1 AND (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) <= 3 THEN GREATEST( GREATEST( 0, COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (COALESCE(idl.metafield_ideal_mix,0) / 100.0)) / NULLIF(f.EFFECTIVE_DEPTH,0) ), 0 ) - COALESCE(f.FULL_SIZE_STORE_COUNT + f.FULL_SIZE_TRANSIT_COUNT,0) ), COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (1.0/100.0)) / NULLIF(f.EFFECTIVE_DEPTH,0) ), 0 ) ) WHEN (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) > 0 AND (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) <= 1 THEN GREATEST( 0, COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (COALESCE(idl.metafield_ideal_mix,0) / 100.0)) / NULLIF(f.EFFECTIVE_DEPTH,0) ), 0 ) - COALESCE(f.FULL_SIZE_STORE_COUNT + f.FULL_SIZE_TRANSIT_COUNT,0) ) ELSE 0 END ) AS OPTIONS_TO_ALLOCATE, CEIL( CEIL( CASE WHEN (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) > 3 THEN GREATEST( GREATEST( 0, COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (COALESCE(idl.metafield_ideal_mix,0) / 100.0)) / NULLIF(f.EFFECTIVE_DEPTH,0) ), 0 ) - COALESCE(f.FULL_SIZE_STORE_COUNT + f.FULL_SIZE_TRANSIT_COUNT,0) ), COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (3.0/100.0)) / NULLIF(f.EFFECTIVE_DEPTH,0) ), 0 ) ) WHEN (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) > 1 AND (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) <= 3 THEN GREATEST( GREATEST( 0, COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (COALESCE(idl.metafield_ideal_mix,0) / 100.0)) / NULLIF(f.EFFECTIVE_DEPTH,0) ), 0 ) - COALESCE(f.FULL_SIZE_STORE_COUNT + f.FULL_SIZE_TRANSIT_COUNT,0) ), COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (1.0/100.0)) / NULLIF(f.EFFECTIVE_DEPTH,0) ), 0 ) ) WHEN (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) > 0 AND (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) <= 1 THEN GREATEST( 0, COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (COALESCE(idl.metafield_ideal_mix,0) / 100.0)) / NULLIF(f.EFFECTIVE_DEPTH,0) ), 0 ) - COALESCE(f.FULL_SIZE_STORE_COUNT + f.FULL_SIZE_TRANSIT_COUNT,0) ) ELSE 0 END ) * COALESCE(f.EFFECTIVE_DEPTH,0) ) AS QTY_TO_ALLOCATE FROM final_metrics f LEFT JOIN store_map sm ON f.Branch_code = sm.Branch_code LEFT JOIN snitch_db.maplemonk.offline_metafield_ideal_mix idl ON f.Branch_code = idl.branch_code AND UPPER(TRIM(f.CATEGORY)) = UPPER(TRIM(idl.category)) AND ( CASE WHEN UPPER(f.CATEGORY) LIke \'%T-SHIRTS%\' THEN UPPER(TRIM(f.META1)) = UPPER(TRIM(idl.meta_1)) AND UPPER(TRIM(f.META2)) = UPPER(TRIM(idl.meta_2)) WHEN UPPER(f.CATEGORY) in (\'SHIRTS\') OR UPPER(f.CATEGORY) IN (\'TROUSERS\',\'JEANS\') THEN UPPER(TRIM(f.META1)) = UPPER(TRIM(idl.meta_1)) ELSE TRUE END ) LEFT JOIN top_price_bucket tpb ON TO_VARCHAR(f.branch_code) = tpb.branch_code AND UPPER(TRIM(f.category)) = UPPER(TRIM(tpb.category)) AND UPPER(TRIM(f.meta1)) = UPPER(TRIM(tpb.meta1)) AND UPPER(TRIM(f.meta2)) = UPPER(TRIM(tpb.meta2)) WHERE (f.STORE_SALES_30D > 0 OR f.STORE_INV_UNITS > 0) AND f.CATEGORY NOT IN (\'BAGS\',\'BELTS\',\'SHOES\',\'SUNGLASSES\') AND idl.cat_mix IS NOT NULL ORDER BY f.Branch_code, f.OPPORTUNITY_STR_PCT DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            